/**
 * The wet scratch channel (owner 2026-10-12: "the scratches sound too dry", "they lie in front of
 * everything"; reference `thoughts/shared/research/2026-10-12_demo-system-scratch-wet-chain.md`).
 * Reference numbers from the Up Rough Demo System's own code (`scratch_routine.scratch_channel`
 * with the DJ render's room 0.3, delay mix 0.16, drive 0.10; `sampler.reverb` short plate + dark
 * room), generated by `tools/scratch-fixtures/gen_scratch_wet_reference.py`:
 * at the reference's own 22,050 Hz:
 *   a 30 ms noise burst: tail (from 5 ms after the burst) to burst energy -17.66 dB (dry: -85 dB)
 *   the room's RT60 (backward integration, T20 x 3) 0.313 s
 * Measured here through the Web Audio bus in an offline render, within 1.5 dB and 10 %.
 */
import { describe, it, expect, beforeAll } from 'vitest';
import { installRealWebAudio } from '@/test/audio/realWebAudio';
import roomFixture from './fixtures/scratch_room_ir.json';

const SR = 48000;
const REF = { tailToBurstDb: -17.66, roomRt60Sec: 0.3128 };

let bus: typeof import('../scratchBus');
let room: typeof import('../scratchRoom');

/** The reference generator's burst: 30 ms of LCG noise (seed 7) under a Hann window, amplitude 0.1. */
function burst(n: number): Float32Array {
  const x = new Float32Array(n);
  let s = 7;
  for (let i = 0; i < n; i++) {
    s = (s * 1103515245 + 12345) % 2147483648;
    x[i] = 0.1 * (s / 2147483648 * 2 - 1) * (0.5 - 0.5 * Math.cos(2 * Math.PI * i / (n - 1)));
  }
  return x;
}

async function renderBurst(make: (ctx: OfflineAudioContext) => { input: AudioNode; setAmbience(a: number): void }, ambience = 0, rate = SR): Promise<Float32Array> {
  const SR = rate;
  const ctx = new OfflineAudioContext(1, Math.round(SR * 1.2), SR);
  const b = make(ctx);
  b.setAmbience(ambience);
  const n = Math.round(0.03 * SR);
  const buf = ctx.createBuffer(1, n, SR);
  buf.getChannelData(0).set(burst(n));
  const src = ctx.createBufferSource();
  src.buffer = buf; src.connect(b.input); src.start(0);
  return (await ctx.startRendering()).getChannelData(0);
}

function tailToBurstDb(y: Float32Array, SR = 48000): number {
  const from = Math.round(0.03 * SR) + Math.round(0.005 * SR);
  let head = 0, tail = 0;
  for (let i = 0; i < y.length; i++) (i < from ? (head += y[i]! * y[i]!) : (tail += y[i]! * y[i]!));
  return 10 * Math.log10(tail / head);
}

function rt60(ir: ArrayLike<number>, rate: number): number {
  const e = new Float64Array(ir.length);
  let acc = 0;
  for (let i = ir.length - 1; i >= 0; i--) { acc += ir[i]! * ir[i]!; e[i] = acc; }
  const at = (db: number) => e.findIndex((v) => 10 * Math.log10(v / e[0]!) <= db);
  return 3 * (at(-25) - at(-5)) / rate;
}

describe('the scratch bus runs wet like the Up Rough scratch channel', () => {
  beforeAll(async () => { installRealWebAudio(); bus = await import('../scratchBus'); room = await import('../scratchRoom'); });

  it('the room is the reference room: its response matches the reference samples, RT60 within 10 %', () => {
    // sample for sample at the reference rate
    const ref = room.scratchRoomResponse(roomFixture.rate);
    const peak = Math.max(...roomFixture.samples.map(Math.abs));
    roomFixture.samples.forEach((v, k) => expect(Math.abs(ref[k * roomFixture.every]! - v), `sample ${k * roomFixture.every}`).toBeLessThan(1e-6 * peak + 1e-9));
    // the same decay at the app's rate
    expect(Math.abs(rt60(room.scratchRoomResponse(SR), SR) - REF.roomRt60Sec) / REF.roomRt60Sec).toBeLessThan(0.1);
  });

  it('a burst through the bus: tail-to-burst energy within 1.5 dB of the reference channel at its rate', async () => {
    // the bus before 2026-10-12 measured -32.83 dB here (room 0.28 x ambience 0.15, a noise room): 15 dB drier
    const old = -32.83;
    const now = tailToBurstDb(await renderBurst((ctx) => bus.createScratchBus(ctx, ctx.destination), bus.ambienceFor('ACCENT')));
    const at22 = tailToBurstDb(await renderBurst((ctx) => bus.createScratchBus(ctx, ctx.destination), bus.ambienceFor('ACCENT'), 22050), 22050);
    console.log(`[wet bus] tail-to-burst: reference ${REF.tailToBurstDb} dB, before ${old.toFixed(2)} dB, now ${now.toFixed(2)} dB (48 kHz), ${at22.toFixed(2)} dB (22.05 kHz)`);
    // the same signal at the reference's own rate: the chain is the reference's (a 48 kHz burst carries
    // energy the 22.05 kHz one cannot, so the 48 kHz figure is reported, not compared)
    expect(Math.abs(at22 - REF.tailToBurstDb)).toBeLessThan(1.5);
    expect(now - old).toBeGreaterThan(10); // the old bus was 15 dB drier
    expect(bus.scratchBusStats.created).toBeGreaterThanOrEqual(2);
  });

  it('the stroke velocity shapes the tone: under 0.5 a low-pass at 2500 + 6000 v, over 0.85 a 3 kHz edge added', async () => {
    const tone = async (hz: number, v: number) => {
      const ctx = new OfflineAudioContext(1, Math.round(SR * 0.4), SR);
      const b = bus.createScratchBus(ctx, ctx.destination, { room: 0, delayMix: 0 });
      b.setTone(v, 0);
      const osc = ctx.createOscillator(); osc.frequency.value = hz;
      const g = ctx.createGain(); g.gain.value = 0.05; osc.connect(g); g.connect(b.input); osc.start(0);
      const y = (await ctx.startRendering()).getChannelData(0);
      let e = 0; for (let i = Math.round(0.2 * SR); i < y.length; i++) e += y[i]! * y[i]!;
      return 10 * Math.log10(e);
    };
    expect(await tone(4000, 0.7) - await tone(4000, 0.2)).toBeGreaterThan(3); // 2500 + 1200 Hz low-pass at v 0.2
    expect(await tone(4000, 0.95) - await tone(4000, 0.7)).toBeGreaterThan(0.3); // + 0.15 x high-pass 3 kHz (about +0.5 dB at 4 kHz)
    expect(Math.abs(await tone(500, 0.95) - await tone(500, 0.7))).toBeLessThan(0.5);
  });
});
